parameters.jsCode:
// PART A - runs once per missed-call request sent by MacroDroid.
// 1) checks the shared secret, 2) turns the caller number into international format,
// 3) skips repeat calls from the same number inside DEDUPE_MINUTES,
// 4) builds the WhatsApp template message + the Google Sheet row.
const cfg = $('Config').first().json;

function normalizePhone(raw, countryCode, localLength) {
  if (raw === undefined || raw === null) return null;
  const s = String(raw).trim();
  if (!s || /unknown|private|hidden|restricted|anonymous/i.test(s)) return null;
  const hadPlus = s.startsWith('+');
  const cc = String(countryCode || '').replace(/\D/g, '');
  let d = s.replace(/\D/g, '');
  if (!d) return null;
  if (hadPlus) {
    // already international, e.g. +923001234567
  } else if (d.startsWith('00')) {
    d = d.slice(2); // 00923001234567 -> 923001234567
  } else if (d.startsWith('0')) {
    d = cc + d.replace(/^0+/, ''); // 03001234567 -> 923001234567
  } else if (d.length <= localLength) {
    d = cc + d; // 3001234567 -> 923001234567
  }
  // anything longer is treated as already international (a "+" sent in a URL can arrive as a space)
  if (d.length < 8 || d.length > 15) return null;
  return d;
}

const store = $getWorkflowStaticData('global');
store.lastSent = store.lastSent || {};
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();
const dedupeMs = Math.max(0, Number(cfg.DEDUPE_MINUTES) || 0) * 60 * 1000;
for (const [num, t] of Object.entries(store.lastSent)) {
  if (nowMs - t > 2 * 24 * 60 * 60 * 1000) delete store.lastSent[num];
}

const out = [];
$input.all().forEach((item, index) => {
  const j = item.json || {};
  const body = j.body && typeof j.body === 'object' ? j.body : {};
  const src = Object.assign({}, j.query || {}, body);

  const secret = String(src.secret ?? '').trim();
  const expected = String(cfg.SHARED_SECRET ?? '').trim();
  if (!expected || /^CHANGE-ME/i.test(expected) || secret !== expected) {
    console.log('Missed call ignored: wrong or missing secret (set SHARED_SECRET in Config)');
    return;
  }

  const phone = normalizePhone(src.caller ?? src.number ?? src.phone, cfg.DEFAULT_COUNTRY_CODE, Number(cfg.LOCAL_NUMBER_LENGTH) || 10);
  if (!phone) {
    console.log('Missed call ignored: no usable caller number', src.caller);
    return;
  }

  if (dedupeMs > 0 && store.lastSent[phone] && nowMs - store.lastSent[phone] < dedupeMs) {
    console.log('Missed call ignored: this number was messaged recently', phone);
    return;
  }
  store.lastSent[phone] = nowMs;

  out.push({
    json: {
      phone,
      name: '',
      wa: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: phone,
        type: 'template',
        template: {
          name: String(cfg.TEMPLATE_NAME || '').trim(),
          language: { code: String(cfg.TEMPLATE_LANGUAGE || 'en').trim() },
          components: [
            { type: 'button', sub_type: 'quick_reply', index: '0', parameters: [{ type: 'payload', payload: 'BOOK_VISIT' }] },
            { type: 'button', sub_type: 'quick_reply', index: '1', parameters: [{ type: 'payload', payload: 'CALL_BACK' }] },
          ],
        },
      },
      row: { phone, status: 'whatsapp_sent', last_call_at: nowIso, updated_at: nowIso },
      sms: null,
    },
    pairedItem: { item: index },
  });
});

return out;

// PART B - turns the raw WhatsApp webhook into simple events:
// book | callback | slot | text | failed. Everything else is ignored.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const nowMs = Date.now();
for (const [id, t] of Object.entries(store.seen)) {
  if (nowMs - t > 24 * 60 * 60 * 1000) delete store.seen[id];
}
const IGNORE_TYPES = ['reaction', 'system', 'unsupported', 'ephemeral', 'request_welcome', 'order'];
// Whole-message opt-out words (English, Roman Urdu, Urdu). Meta requires honouring opt-outs.
const STOP_WORDS = ['stop', 'stop messages', 'unsubscribe', 'opt out', 'optout', 'band karo', 'bund karo',
  'mat bhejo', 'message mat bhejo', 'بند کرو', 'میسج مت بھیجو'];
function isStop(t) {
  const s = String(t || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
  return STOP_WORDS.includes(s);
}

const out = [];
$input.all().forEach((item, index) => {
  const v = item.json || {};
  const contacts = Array.isArray(v.contacts) ? v.contacts : [];

  // Delivery reports: only "failed" ones matter (the trigger only sends failed ones anyway)
  for (const st of Array.isArray(v.statuses) ? v.statuses : []) {
    if (st.status !== 'failed') continue;
    const err = (Array.isArray(st.errors) && st.errors[0]) || {};
    out.push({
      json: {
        event: 'failed',
        phone: String(st.recipient_id || ''),
        name: '',
        message_id: String(st.id || ''),
        error_code: Number(err.code) || 0,
        error_title: String(err.title || err.message || 'unknown error'),
        text: '',
        payload: '',
        slot_id: '',
        stop: false,
      },
      pairedItem: { item: index },
    });
  }

  for (const m of Array.isArray(v.messages) ? v.messages : []) {
    const type = String(m.type || '');
    if (IGNORE_TYPES.includes(type)) continue;
    if (m.id) {
      if (store.seen[m.id]) continue; // WhatsApp sometimes delivers the same message twice
      store.seen[m.id] = nowMs;
    }
    const phone = String(m.from || '');
    if (!phone) continue;
    const contact = contacts.find((c) => c.wa_id === phone) || contacts[0] || {};
    const name = String((contact.profile && contact.profile.name) || '').slice(0, 60);

    let event = 'text';
    let payload = '';
    let slotId = '';
    let text = '';

    if (type === 'button') {
      payload = (m.button && (m.button.payload || m.button.text)) || '';
      text = (m.button && m.button.text) || '';
      event = 'button';
    } else if (type === 'interactive') {
      const it = m.interactive || {};
      if (it.type === 'list_reply') {
        event = 'slot';
        slotId = (it.list_reply && it.list_reply.id) || '';
        text = (it.list_reply && it.list_reply.title) || '';
      } else if (it.type === 'button_reply') {
        event = 'button';
        payload = (it.button_reply && it.button_reply.id) || '';
        text = (it.button_reply && it.button_reply.title) || '';
      } else {
        text = '[interactive reply]';
      }
    } else if (type === 'text') {
      text = (m.text && m.text.body) || '';
    } else if (type === 'location') {
      const L = m.location || {};
      const place = [L.name, L.address].filter(Boolean).join(', ');
      text = 'Location: ' + (place ? place + ' - ' : '') + 'https://maps.google.com/?q=' + L.latitude + ',' + L.longitude;
    } else {
      text = '[' + (type || 'unknown') + ' message received]';
    }

    if (event === 'button') {
      const p = String(payload).toUpperCase();
      if (p.includes('BOOK')) event = 'book';
      else if (p.includes('CALL')) event = 'callback';
      else { event = 'text'; text = text || payload; }
    }
    if (event === 'slot' && !String(slotId).startsWith('SLOT|')) event = 'text';

    out.push({
      json: {
        event,
        phone,
        name,
        message_id: String(m.id || ''),
        payload: String(payload),
        slot_id: String(slotId),
        text: String(text).slice(0, 1000),
        stop: type === 'text' && isStop(text),
        error_code: 0,
        error_title: '',
      },
      pairedItem: { item: index },
    });
  }
});

return out;

// Builds up to 10 free time slots from the calendar's busy times
// and turns them into a WhatsApp list message.
const cfg = $('Config').first().json;
const ev = $('Parse WhatsApp Event').item.json;
const zone = String(cfg.TIMEZONE || 'Asia/Karachi');
const now = DateTime.now().setZone(zone);
const nowIso = new Date().toISOString();

const calendars = ($json && $json.calendars) || {};
const firstCal = Object.values(calendars)[0] || {};
const busy = (Array.isArray(firstCal.busy) ? firstCal.busy : []).map((b) => ({
  s: DateTime.fromISO(String(b.start)).toMillis(),
  e: DateTime.fromISO(String(b.end)).toMillis(),
}));

const slotMinutes = Math.max(15, Number(cfg.SLOT_MINUTES) || 60);
const noticeMs = Math.max(0, Number(cfg.MIN_NOTICE_MINUTES) || 0) * 60 * 1000;
const daysAhead = Math.min(Math.max(Number(cfg.DAYS_AHEAD) || 5, 1), 14);
const workDays = String(cfg.WORK_DAYS || '1,2,3,4,5,6')
  .split(',').map((x) => Number(String(x).trim())).filter((n) => n >= 1 && n <= 7);
const times = String(cfg.SLOT_TIMES || '10:00,13:00,16:00')
  .split(',').map((t) => String(t).trim()).filter(Boolean);

const slots = [];
for (let d = 0; d <= daysAhead && slots.length < 10; d++) {
  const day = now.startOf('day').plus({ days: d });
  if (!workDays.includes(day.weekday)) continue;
  for (const t of times) {
    const parts = t.split(':');
    const hh = Number(parts[0]);
    const mm = Number(parts[1] || 0);
    if (!Number.isFinite(hh) || !Number.isFinite(mm)) continue;
    const start = day.set({ hour: hh, minute: mm, second: 0, millisecond: 0 });
    const end = start.plus({ minutes: slotMinutes });
    if (start.toMillis() < now.toMillis() + noticeMs) continue;
    const clash = busy.some((b) => start.toMillis() < b.e && end.toMillis() > b.s);
    if (clash) continue;
    slots.push({ start, end });
    if (slots.length >= 10) break;
  }
}

const business = String(cfg.BUSINESS_NAME || '').trim();
const retry = ev.event === 'slot';

if (!slots.length) {
  return {
    json: {
      phone: ev.phone,
      name: ev.name,
      wa: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: ev.phone,
        type: 'interactive',
        interactive: {
          type: 'button',
          body: { text: 'Sorry, we are fully booked for the next few days. Tap below and we will call you to find a time.' },
          action: { buttons: [{ type: 'reply', reply: { id: 'CALL_BACK', title: 'Call me back' } }] },
        },
      },
      row: { phone: ev.phone, name: ev.name || undefined, status: 'no_free_slots', updated_at: nowIso },
      sms: null,
    },
  };
}

const rows = slots.map((s) => ({
  id: 'SLOT|' + s.start.toISO({ suppressMilliseconds: true }) + '|' + slotMinutes,
  title: s.start.setLocale('en').toFormat('ccc d LLL, h:mm a').slice(0, 24),
  description: (slotMinutes + ' min visit').slice(0, 72),
}));

const interactive = {
  type: 'list',
  header: { type: 'text', text: 'Book a visit' },
  body: {
    text: retry
      ? 'Sorry, that time is no longer available. Here are the latest free times:'
      : 'Great! Pick a time that suits you.',
  },
  action: {
    button: 'See free times',
    sections: [{ title: 'Available times', rows }],
  },
};
if (business) interactive.footer = { text: business.slice(0, 60) };

return {
  json: {
    phone: ev.phone,
    name: ev.name,
    wa: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: ev.phone,
      type: 'interactive',
      interactive,
    },
    row: { phone: ev.phone, name: ev.name || undefined, status: 'choosing_slot', updated_at: nowIso },
    sms: null,
  },
};

