// Runs after the call-back reminder is added to the owner's calendar.
const ev = $('Parse WhatsApp Event').item.json;
const nowIso = new Date().toISOString();

return {
  json: {
    phone: ev.phone,
    name: ev.name,
    wa: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: ev.phone,
      type: 'text',
      text: { body: 'Thanks! We will call you back shortly on this number.', preview_url: false },
    },
    row: { phone: ev.phone, name: ev.name || undefined, status: 'callback_requested', updated_at: nowIso },
    sms: null,
  },
};

// Reads the time slot the customer picked (row id looks like SLOT|2026-09-29T10:00:00+05:00|60)
const cfg = $('Config').first().json;
const zone = String(cfg.TIMEZONE || 'Asia/Karachi');
const parts = String($json.slot_id || '').split('|');
const start = DateTime.fromISO(String(parts[1] || ''), { setZone: true });
const minutes = Math.max(15, Number(parts[2]) || Number(cfg.SLOT_MINUTES) || 60);
const valid = start.isValid && start.toMillis() > Date.now();
const end = valid ? start.plus({ minutes }) : null;

return {
  json: {
    phone: $json.phone,
    name: $json.name,
    slot_valid: valid,
    slot_start: valid ? start.toISO({ suppressMilliseconds: true }) : '',
    slot_end: valid ? end.toISO({ suppressMilliseconds: true }) : '',
    slot_label: valid ? start.setZone(zone).setLocale('en').toFormat("cccc d LLLL 'at' h:mm a") : '',
  },
};

