parameters.jsCode:
// Runs after the calendar event is created: confirms the booking on WhatsApp
// and asks for the address + problem details.
const slot = $('Check Slot').item.json;
const nowIso = new Date().toISOString();
const text =
  'You are booked for ' + slot.slot_label + '.\n\n' +
  'Please reply with your address and a short description of the problem. ' +
  'You can also share your location using the attach (clip) button.';

return {
  json: {
    phone: slot.phone,
    name: slot.name,
    wa: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: slot.phone,
      type: 'text',
      text: { body: text, preview_url: false },
    },
    row: {
      phone: slot.phone,
      name: slot.name || undefined,
      status: 'booked_awaiting_details',
      slot: slot.slot_label,
      slot_start: slot.slot_start,
      event_id: String($json.id || ''),
      details: '',
      updated_at: nowIso,
    },
    sms: null,
  },
};

// Decides what to do with a normal message (text, location, voice note...).
// - STOP / unsubscribe -> opted out (Part A checks the sheet and stops messaging them)
// - booked customer with an upcoming visit -> save it as visit details (sheet + calendar);
//   "cancel" / "reschedule" flags the booking so the owner calls them
// - asked for a call-back -> short thank-you
// - anyone else -> reply with the two buttons (Book a visit / Call me back)
const cfg = $('Config').first().json;
const ev = $('Parse WhatsApp Event').item.json;
const lead = $json && String($json.phone || '') !== '' ? $json : null;
const status = lead ? String(lead.status || '') : '';
const nowIso = new Date().toISOString();
const text = String(ev.text || '').trim();
const name = ev.name || (lead && lead.name) || '';
const business = String(cfg.BUSINESS_NAME || '').trim();

function textMessage(body) {
  return {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: ev.phone,
    type: 'text',
    text: { body, preview_url: false },
  };
}

if (ev.stop) {
  return {
    json: {
      phone: ev.phone,
      name,
      update_event: false,
      wa: textMessage('Okay, we will not send you any more messages. If you need us, just call or message us any time.'),
      row: { phone: ev.phone, name: name || undefined, status: 'opted_out', last_message: text, updated_at: nowIso },
      sms: null,
    },
  };
}

const slotStart = lead && lead.slot_start ? DateTime.fromISO(String(lead.slot_start), { setZone: true }) : null;
const upcoming = !!(slotStart && slotStart.isValid && slotStart.toMillis() > Date.now());
const bookingOpen = status.startsWith('booked') || status === 'change_requested';

if (lead && lead.event_id && bookingOpen && upcoming) {
  const wantsChange = /\b(cancel|cancell?ed|reschedule|postpone)\b/i.test(text) ||
    /\b(change|another|different)\s+(the\s+)?(time|date|day|slot)\b/i.test(text);
  const flagged = wantsChange || status === 'change_requested';
  const oldDetails = String(lead.details || '').trim();
  const note = wantsChange ? '[Asked to change or cancel] ' + text : text;
  const details = ((oldDetails ? oldDetails + '\n' : '') + note).slice(0, 2000);
  const summary = (flagged ? 'CHANGE/CANCEL? ' : '') + 'Visit: ' + (name || 'WhatsApp customer') + ' (+' + ev.phone + ')';
  const description =
    (flagged ? 'CUSTOMER ASKED TO CHANGE OR CANCEL - please call them.\n\n' : '') +
    'Booked via WhatsApp (missed-call bot)\n' +
    'Customer: ' + (name || 'Unknown') + '\n' +
    'Phone: +' + ev.phone + '\n' +
    'WhatsApp: https://wa.me/' + ev.phone + '\n\n' +
    'Details from customer:\n' + details;
  let reply = 'Got it, we have added that to your booking.';
  if (wantsChange) reply = 'No problem. We will call you shortly to change or cancel your booking.';
  else if (!oldDetails) reply = 'Thank you! We have added this to your booking for ' + (lead.slot || 'your visit') + '. See you then.';
  return {
    json: {
      phone: ev.phone,
      name,
      update_event: true,
      event_id: String(lead.event_id),
      event_summary: summary,
      event_description: description,
      wa: textMessage(reply),
      row: {
        phone: ev.phone,
        name: name || undefined,
        status: flagged ? 'change_requested' : 'booked',
        details,
        last_message: text,
        updated_at: nowIso,
      },
      sms: null,
    },
  };
}

if (status === 'callback_requested') {
  return {
    json: {
      phone: ev.phone,
      name,
      update_event: false,
      wa: textMessage('Thanks! We have your message and will call you back soon.'),
      row: { phone: ev.phone, name: name || undefined, last_message: text, updated_at: nowIso },
      sms: null,
    },
  };
}

return {
  json: {
    phone: ev.phone,
    name,
    update_event: false,
    wa: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: ev.phone,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: {
          text:
            'Hi' + (name ? ' ' + name : '') + '! Thanks for your message' +
            (business ? ' to ' + business : '') +
            '. Would you like to book a visit, or should we call you back?',
        },
        action: {
          buttons: [
            { type: 'reply', reply: { id: 'BOOK_VISIT', title: 'Book a visit' } },
            { type: 'reply', reply: { id: 'CALL_BACK', title: 'Call me back' } },
          ],
        },
      },
    },
    row: {
      phone: ev.phone,
      name: name || undefined,
      status: !lead || status === 'opted_out' ? 'new_chat' : undefined,
      last_message: text,
      updated_at: nowIso,
    },
    sms: null,
  },
};

// A WhatsApp message could not be delivered.
// Error 131026 = the number is not on WhatsApp -> optional SMS backup through the Android phone.
const cfg = $('Config').first().json;
const nowIso = new Date().toISOString();
const notOnWhatsApp = Number($json.error_code) === 131026;
const smsUrl = String(cfg.MACRODROID_SMS_WEBHOOK || '').trim();
const sendSms = notOnWhatsApp && /^https:\/\//i.test(smsUrl);
const smsText = String(cfg.SMS_BACKUP_TEXT || '')
  .split('{business}').join(String(cfg.BUSINESS_NAME || '').trim())
  .slice(0, 300);

const row = {
  phone: $json.phone,
  last_error: ($json.error_code + ' ' + $json.error_title).trim().slice(0, 250),
  updated_at: nowIso,
};
if (notOnWhatsApp) row.status = sendSms ? 'no_whatsapp_sms_sent' : 'no_whatsapp';

return {
  json: {
    phone: $json.phone,
    name: '',
    wa: null,
    row,
    sms: sendSms && smsText ? { url: smsUrl, to: '+' + $json.phone, text: smsText } : null,
  },
};

// Shapes the Google Sheet row. Only the columns listed here are written;
// other columns in the row are left as they are.
const r = $('Reply Ready').item.json;
const row = Object.assign({}, r.row || {});
const err = $json.error;
if (err) {
  const msg = typeof err === 'string' ? err : (err.message || err.description || JSON.stringify(err));
  row.last_error = String(msg).slice(0, 250);
  if (row.status === 'whatsapp_sent') row.status = 'whatsapp_error';
} else if (r.wa && row.last_error === undefined) {
  row.last_error = '';
}
row.phone = String(row.phone || r.phone || '');
for (const key of Object.keys(row)) {
  if (row[key] === undefined || row[key] === null) delete row[key];
}
return { json: row };

// Drops missed calls from people who opted out (status "opted_out" in the Leads sheet).
// To stop messaging someone who asked by phone, type opted_out in their status cell.
const out = [];
$input.all().forEach((item, index) => {
  const prepared = $('Prepare Missed Call').itemMatching(index).json;
  const status = String((item.json && item.json.status) || '').trim().toLowerCase();
  if (status === 'opted_out') {
    console.log('Missed call ignored: caller opted out', prepared.phone);
    return;
  }
  out.push({ json: prepared, pairedItem: { item: index } });
});
return out;
